    service Greeter {
        rpc GetErrResp (HelloRequest) returns (HelloReply) {}
    }
    message HelloRequest {
        string name = 1;
        repeated string items = 2;
    }
    message HelloReply {
        string message = 1;
        repeated string items = 2;
    }
    message ErrorDetail {
        int64 code = 1;
        string message = 2;
